// documentsUsage displays the usage of the documents command and its
// subcommands.
func documentsUsage() {
	fmt.Fprintln(os.Stderr, "Service is the documents service interface.")
	fmt.Fprintf(os.Stderr, "Usage:\n    %s [globalflags] documents COMMAND [flags]\n\n", os.Args[0])
	fmt.Fprintln(os.Stderr, "COMMAND:")
	fmt.Fprintln(os.Stderr, "    list: List implements list.")
	fmt.Fprintln(os.Stderr, "    upload: Upload implements upload.")
	fmt.Fprintln(os.Stderr, "    delete: Delete implements delete.")
	fmt.Fprintln(os.Stderr, "    display: Display implements display.")
	fmt.Fprintln(os.Stderr, "    download-zip: DownloadZip implements download_zip.")
	fmt.Fprintln(os.Stderr, "    url: URL implements url.")
	fmt.Fprintln(os.Stderr, "    docx: Docx implements docx.")
	fmt.Fprintln(os.Stderr, "    process-metadata: Queue a single document for deferred metadata classification. Spawns a background goroutine that runs the classifier against the document's stored text twin.")
	fmt.Fprintln(os.Stderr, "    process-metadata-batch: Queue many documents for deferred metadata classification. Either pass an explicit document_ids list, or a filter like 'unprocessed' to enqueue every matching row.")
	fmt.Fprintln(os.Stderr, "    metadata-queue: Return the current metadata-processing queue counts grouped by metadata_status.")
	fmt.Fprintln(os.Stderr, "    patch-metadata: Apply user overrides to a document's classifier output. When confirm=true, flips metadata_status to user_confirmed.")
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "Additional help:")
	fmt.Fprintf(os.Stderr, "    %s documents COMMAND --help\n", os.Args[0])
}
